"""The C data files grit writes for a tile sheet, without running grit: a header and a source with the tile words and
the 16 palette words."""

from __future__ import annotations

import re
from collections.abc import Sequence
from dataclasses import dataclass

DEFAULT_HEADER = """\
//{{{{BLOCK({c_name})

//======================================================================
//
//\t{c_name}, {width}x{height}@4,
//\t+ palette 16 entries, not compressed
//\t+ {tile_count} tiles not compressed
//\tGenerated by uppercut-gba-asset-export
//
//======================================================================

#ifndef GRIT_{C_NAME}_H
#define GRIT_{C_NAME}_H

#define {c_name}TilesLen {tiles_len}
extern const unsigned int {c_name}Tiles[{word_count}];

#define {c_name}PalLen 32
extern const unsigned short {c_name}Pal[16];

#endif // GRIT_{C_NAME}_H

//}}}}BLOCK({c_name})
"""

DEFAULT_SOURCE = """\
//{{{{BLOCK({c_name})

#include "{file_name}.h"

const unsigned int {c_name}Tiles[{word_count}] __attribute__((aligned(4))) =
{{
{tile_rows}
}};

const unsigned short {c_name}Pal[16] __attribute__((aligned(4))) =
{{
{palette_rows}
}};

//}}}}BLOCK({c_name})
"""


def c_name(value: str) -> str:
    """A C identifier from a file name: every character that is not a letter, digit or underscore becomes ``_``."""
    return re.sub(r"[^0-9A-Za-z_]", "_", value)


@dataclass(frozen=True)
class GritFiles:
    header: str
    source: str


def _rows(values: Sequence[int], per_line: int, digits: int, indent: str, separator: str, trailing_comma: bool) -> str:
    lines = []
    for start in range(0, len(values), per_line):
        chunk = values[start : start + per_line]
        text = separator.join(f"0x{v:0{digits}X}" for v in chunk)
        lines.append(indent + text + ("," if trailing_comma else ""))
    return "\n".join(lines)


def grit_files(
    name: str,
    words: Sequence[int],
    palette: Sequence[int],
    *,
    width: int,
    height: int,
    header_template: str = DEFAULT_HEADER,
    source_template: str = DEFAULT_SOURCE,
    indent: str = "\t",
    palette_indent: str | None = None,
    separator: str = ",",
    palette_per_line: int = 8,
    trailing_comma: bool = True,
    palette_trailing_comma: bool | None = None,
) -> GritFiles:
    """The ``name.h`` and ``name.c`` text for one sheet.

    ``words`` are the tile words (``tile_words``), ``palette`` the 16 BGR555 words. The default templates follow grit's
    own output: a ``BLOCK`` banner, ``NameTiles`` and ``NamePal`` arrays aligned to four bytes, and ``NameTilesLen`` and
    ``NamePalLen`` constants. A project whose files carry its own header comment or guard passes its own templates;
    they are ``str.format`` strings (write ``{{`` and ``}}`` for literal braces) that can use ``name`` and ``file_name``
    (the text given), ``c_name`` and ``C_NAME`` (the identifier and its upper case), ``width``, ``height``,
    ``tile_count``, ``tiles_len`` (bytes), ``word_count``, and, in the source, ``tile_rows`` and ``palette_rows``.
    ``indent``, ``separator``, ``palette_per_line`` and ``trailing_comma`` set how the numbers are laid out;
    ``palette_indent`` and ``palette_trailing_comma`` set the palette's own when it differs from the tiles'.
    """
    if len(palette) != 16:
        raise ValueError(f"a 4bpp palette has 16 entries, not {len(palette)}")
    if len(words) % 8:
        raise ValueError("tile words come eight to a tile")
    ident = c_name(name)
    fields = {
        "name": name,
        "file_name": name,
        "c_name": ident,
        "C_NAME": ident.upper(),
        "width": width,
        "height": height,
        "tile_count": len(words) // 8,
        "tiles_len": len(words) * 4,
        "word_count": len(words),
        "tile_rows": _rows(words, 8, 8, indent, separator, trailing_comma),
        "palette_rows": _rows(palette, palette_per_line, 4, indent if palette_indent is None else palette_indent, separator, trailing_comma if palette_trailing_comma is None else palette_trailing_comma),
    }
    return GritFiles(header_template.format(**fields), source_template.format(**fields))
